-- Backfill order_items.quantity in batches to avoid long-running transaction
-- Process in chunks to minimize lock contention on a potentially large table
DO $$
DECLARE
    batch_size INTEGER := 1000;
    rows_updated INTEGER;
BEGIN
    LOOP
        UPDATE order_items
        SET quantity = 1
        WHERE id IN (
            SELECT id 
            FROM order_items 
            WHERE quantity != 1
            ORDER BY id
            LIMIT batch_size
        );

        GET DIAGNOSTICS rows_updated = ROW_COUNT;
        EXIT WHEN rows_updated = 0;

        -- Brief pause between batches to allow concurrent transactions through
        PERFORM pg_sleep(0.05);
    END LOOP;
END $$;",
